CREATE TABLE ibexa_content_type (id SERIAL NOT NULL, status INT DEFAULT 0 NOT NULL, always_available INT DEFAULT 0 NOT NULL, contentobject_name VARCHAR(255) DEFAULT NULL, created INT DEFAULT 0 NOT NULL, creator_id INT DEFAULT 0 NOT NULL, identifier VARCHAR(50) DEFAULT '' NOT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, is_container INT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INT DEFAULT 0 NOT NULL, modifier_id INT DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT '' NOT NULL, serialized_description_list TEXT DEFAULT NULL, serialized_name_list TEXT DEFAULT NULL, sort_field INT DEFAULT 1 NOT NULL, sort_order INT DEFAULT 1 NOT NULL, url_alias_name VARCHAR(255) DEFAULT NULL, PRIMARY KEY(id, status));
